# 1. Definition of Fast Cross Residual Extraction Function (Utilizing QR Decomposition, Including Missing Value Control)
EWAS_RegressOut <- function(Y_raw, X, chunk=20000) { Keep <- complete.cases(X); X_sub <- model.matrix(~., data=as.data.frame(X)[Keep, , drop=FALSE]); QR_X <- qr(X_sub); Res <- matrix(NA, nrow=nrow(X), ncol=nrow(Y_raw), dimnames=list(rownames(X), rownames(Y_raw))); for(i in seq(1, nrow(Y_raw), by=chunk)) { idx <- i:min(i+chunk-1, nrow(Y_raw)); Y_chunk <- t(as.matrix(Y_raw[idx, Keep, drop=FALSE])); na_idx <- is.na(Y_chunk); if(any(na_idx)) { Y_chunk[na_idx] <- colMeans(Y_chunk, na.rm=TRUE)[col(Y_chunk)][na_idx] }; R_chunk <- qr.resid(QR_X, Y_chunk); R_chunk[na_idx] <- NA; Res[Keep, idx] <- R_chunk }; gc(); return(Res) }

# 2.Cohort/Gender Confounding Variable Integration Matrix (Combination of Phenotype-Intra-Confounding Variables + Cell Composition, Rowname Matching)
Cov_A01_M <- cbind(A01_m04_LIP_M[, 4:8], ASAS0400c[match(rownames(A01_m04_LIP_M), rownames(ASAS0400c)), ]); Cov_A01_F <- cbind(A01_m04_LIP_F[, 4:8], ASAS0400c[match(rownames(A01_m04_LIP_F), rownames(ASAS0400c)), ])
Cov_A05_M <- cbind(A05_m15_LIP_M[, 4:8], ASAS1528c[match(rownames(A05_m15_LIP_M), rownames(ASAS1528c)), ]); Cov_A05_F <- cbind(A05_m15_LIP_F[, 4:8], ASAS1528c[match(rownames(A05_m15_LIP_F), rownames(ASAS1528c)), ])
Cov_C01_M <- cbind(C01_m08_LIP_M[, 4:7], CITY0822c[match(rownames(C01_m08_LIP_M), rownames(CITY0822c)), ]); Cov_C01_F <- cbind(C01_m08_LIP_F[, 4:7], CITY0822c[match(rownames(C01_m08_LIP_F), rownames(CITY0822c)), ])

# 3. Extract Residuals from Lipid Variables (Transposed input to match feature-by-sample orientation)
A01_m04_LIP_M <- EWAS_RegressOut(t(A01_m04_LIP_M[, 1:3]), Cov_A01_M); A01_m04_LIP_F <- EWAS_RegressOut(t(A01_m04_LIP_F[, 1:3]), Cov_A01_F)
A05_m15_LIP_M <- EWAS_RegressOut(t(A05_m15_LIP_M[, 1:3]), Cov_A05_M); A05_m15_LIP_F <- EWAS_RegressOut(t(A05_m15_LIP_F[, 1:3]), Cov_A05_F)
C01_m08_LIP_M <- EWAS_RegressOut(t(C01_m08_LIP_M[, 1:3]), Cov_C01_M); C01_m08_LIP_F <- EWAS_RegressOut(t(C01_m08_LIP_F[, 1:3]), Cov_C01_F)

# 4. Batch extraction of Beta Value Methylation residuals (input in the form of Samples x CpGs using t()) / M Value Methylation Residual Batch Extraction
